<div class="toolbar"><form class="filterbar" method="get"><input name="q" value="<?= e($q) ?>" placeholder="Search media…"><button class="btn" type="submit">Search</button></form></div><section class="panel upload-panel"><div><h2>Upload media</h2><p>JPEG, PNG, WEBP or GIF up to the configured upload limit. Originals stay outside the public web root.</p></div><form class="upload-form" method="post" action="/admin/media" enctype="multipart/form-data"><?= csrf_field() ?><input type="file" name="media" accept="image/jpeg,image/png,image/webp,image/gif" required><button class="btn primary" type="submit">Upload image</button></form></section>
<div class="media-grid modern"><?php foreach($items as $item):?><article class="media-card"><button class="media-preview" type="button" data-copy="/media/<?= (int)$item['id'] ?>" title="Click to copy URL"><img src="/media/<?= (int)$item['id'] ?>" alt="<?= e($item['alt_text']??'') ?>"></button><div class="media-body"><strong title="<?= e($item['original_name']) ?>"><?= e($item['original_name']) ?></strong><small><?= e($item['mime_type']) ?> · <?= number_format(((int)$item['size_bytes'])/1024,1) ?> KB</small><form method="post" action="/admin/media/<?= (int)$item['id'] ?>"><?= csrf_field() ?><input name="alt_text" value="<?= e($item['alt_text']??'') ?>" placeholder="Alternative text"><button class="btn small" type="submit">Save alt</button></form><form method="post" action="/admin/media/<?= (int)$item['id'] ?>/delete" data-confirm="Delete this media file?"><?= csrf_field() ?><button class="btn small danger" type="submit">Delete</button></form></div></article><?php endforeach;?><?php if(!$items):?><div class="empty-state"><strong>No media found</strong><p>Upload your first image to start building the media library.</p></div><?php endif;?></div>